sys_script_include.script:
var ValidateAttachments= Class.create();
ValidateAttachments.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getFileName: function() {
        var attachmentId = this.getParameter('sysparm_attachment_id');
        var gr = new GlideRecord('sys_attachment');
        if (gr.get(attachmentId)) {
            return gr.file_name;
        }
        return '';
    }
});
